create extension if not exists pgcrypto;
do $$ begin create type course_status as enum ('DRAFT','ACTIVE','ARCHIVED'); exception when duplicate_object then null; end $$;
do $$ begin create type material_type as enum ('TEXT','LINK','FILE'); exception when duplicate_object then null; end $$;
do $$ begin create type question_type as enum ('SINGLE_CHOICE'); exception when duplicate_object then null; end $$;
do $$ begin create type import_type as enum ('QUESTIONS','EMPLOYEES'); exception when duplicate_object then null; end $$;
do $$ begin create type import_status as enum ('PENDING','PROCESSING','COMPLETED','FAILED'); exception when duplicate_object then null; end $$;
do $$ begin create type exam_status as enum ('DRAFT','ACTIVE','ARCHIVED'); exception when duplicate_object then null; end $$;
do $$ begin create type selection_mode as enum ('RANDOM','ALL'); exception when duplicate_object then null; end $$;
do $$ begin create type review_policy as enum ('AFTER_EACH_SUBMISSION','AFTER_FINAL_LOCK'); exception when duplicate_object then null; end $$;
do $$ begin create type batch_status as enum ('DRAFT','OPEN','CLOSED'); exception when duplicate_object then null; end $$;
do $$ begin create type learner_status as enum ('NOT_STARTED','READING','READY_FOR_EXAM','IN_PROGRESS','PASSED','FAILED','EXPIRED','LOCKED'); exception when duplicate_object then null; end $$;
do $$ begin create type attempt_status as enum ('IN_PROGRESS','SUBMITTED'); exception when duplicate_object then null; end $$;

create or replace function set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create table if not exists departments(id uuid primary key default gen_random_uuid(),department_code varchar(50) not null unique,department_name varchar(200) not null,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists employees(id uuid primary key default gen_random_uuid(),employee_code varchar(50) not null unique,full_name varchar(200) not null,department_id uuid references departments(id) on delete set null,position_name varchar(200),email varchar(255),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_employees_department on employees(department_id); create index if not exists idx_employees_search on employees(lower(employee_code),lower(full_name)) where is_active;
create table if not exists training_courses(id uuid primary key default gen_random_uuid(),course_code varchar(50) not null unique,course_name varchar(255) not null,description text,version varchar(30),status course_status not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists learning_materials(id uuid primary key default gen_random_uuid(),course_id uuid not null references training_courses(id) on delete restrict,title varchar(255) not null,material_type material_type not null default 'TEXT',content text,file_url text,sort_order integer not null default 0 check(sort_order>=0),is_required boolean not null default true,estimated_minutes integer check(estimated_minutes is null or estimated_minutes>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((material_type='TEXT' and content is not null) or (material_type in ('LINK','FILE') and file_url is not null)));
create index if not exists idx_materials_course_order on learning_materials(course_id,sort_order);
create table if not exists question_banks(id uuid primary key default gen_random_uuid(),bank_code varchar(50) not null unique,bank_name varchar(255) not null,course_id uuid references training_courses(id) on delete set null,description text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists import_jobs(id uuid primary key default gen_random_uuid(),import_type import_type not null,file_name varchar(255) not null,status import_status not null default 'PENDING',total_rows integer not null default 0 check(total_rows>=0),success_rows integer not null default 0 check(success_rows>=0),failed_rows integer not null default 0 check(failed_rows>=0),error_details jsonb not null default '[]',created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists questions(id uuid primary key default gen_random_uuid(),bank_id uuid not null references question_banks(id) on delete restrict,question_code varchar(50) not null,question_text text not null,question_type question_type not null default 'SINGLE_CHOICE',explanation text,default_points numeric(8,2) not null default 1 check(default_points>0),is_active boolean not null default true,import_job_id uuid references import_jobs(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(bank_id,question_code));
create index if not exists idx_questions_bank_active on questions(bank_id,is_active);
create table if not exists question_options(id uuid primary key default gen_random_uuid(),question_id uuid not null references questions(id) on delete cascade,option_code varchar(10) not null,option_text text not null,is_correct boolean not null default false,sort_order integer not null default 0 check(sort_order>=0),created_at timestamptz not null default now(),unique(question_id,option_code),unique(question_id,sort_order));
create unique index if not exists uq_question_options_one_correct on question_options(question_id) where is_correct; create index if not exists idx_question_options_question on question_options(question_id,sort_order);
create table if not exists exams(id uuid primary key default gen_random_uuid(),exam_code varchar(50) not null unique,course_id uuid not null references training_courses(id) on delete restrict,exam_name varchar(255) not null,instructions text,default_question_count integer not null check(default_question_count>0),default_time_limit_minutes integer not null check(default_time_limit_minutes>0),default_max_attempts integer not null default 1 check(default_max_attempts>0),default_pass_score numeric(5,2) not null default 80 check(default_pass_score between 0 and 100),shuffle_questions boolean not null default true,shuffle_options boolean not null default true,stop_on_pass boolean not null default true,require_material_completion boolean not null default false,review_policy review_policy not null default 'AFTER_FINAL_LOCK',status exam_status not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,course_id));
create table if not exists exam_bank_rules(id uuid primary key default gen_random_uuid(),exam_id uuid not null references exams(id) on delete cascade,bank_id uuid not null references question_banks(id) on delete restrict,selection_mode selection_mode not null default 'RANDOM',question_count integer check(question_count is null or question_count>0),created_at timestamptz not null default now(),unique(exam_id,bank_id),check(selection_mode='ALL' or (selection_mode='RANDOM' and question_count>0)));
create table if not exists training_batches(id uuid primary key default gen_random_uuid(),batch_code varchar(50) not null unique,batch_name varchar(255) not null,course_id uuid not null references training_courses(id) on delete restrict,exam_id uuid not null references exams(id) on delete restrict,public_token uuid not null default gen_random_uuid() unique,start_at timestamptz,due_at timestamptz,status batch_status not null default 'DRAFT',question_count integer not null check(question_count>0),time_limit_minutes integer not null check(time_limit_minutes>0),max_attempts integer not null check(max_attempts>0),pass_score numeric(5,2) not null check(pass_score between 0 and 100),shuffle_questions boolean not null default true,shuffle_options boolean not null default true,stop_on_pass boolean not null default true,review_policy review_policy not null,require_material_completion boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint fk_batch_exam_course foreign key(exam_id,course_id) references exams(id,course_id) on delete restrict,check(due_at is null or start_at is null or due_at>start_at));
create index if not exists idx_batches_status_due on training_batches(status,due_at); create index if not exists idx_batches_token on training_batches(public_token);
create table if not exists batch_bank_rules(id uuid primary key default gen_random_uuid(),batch_id uuid not null references training_batches(id) on delete cascade,source_exam_bank_rule_id uuid references exam_bank_rules(id) on delete set null,bank_id uuid not null references question_banks(id) on delete restrict,selection_mode selection_mode not null,question_count integer check(question_count is null or question_count>0),created_at timestamptz not null default now(),unique(batch_id,bank_id),check(selection_mode='ALL' or (selection_mode='RANDOM' and question_count>0)));
create table if not exists batch_employees(id uuid primary key default gen_random_uuid(),batch_id uuid not null references training_batches(id) on delete restrict,employee_id uuid not null references employees(id) on delete restrict,assigned_at timestamptz not null default now(),current_status learner_status not null default 'NOT_STARTED',attempts_used integer not null default 0 check(attempts_used>=0),best_score numeric(5,2) check(best_score between 0 and 100),last_score numeric(5,2) check(last_score between 0 and 100),last_attempt_at timestamptz,completed_at timestamptz,locked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(batch_id,employee_id));
create index if not exists idx_batch_employees_batch_status on batch_employees(batch_id,current_status); create index if not exists idx_batch_employees_employee on batch_employees(employee_id);
create table if not exists employee_material_progress(id uuid primary key default gen_random_uuid(),batch_employee_id uuid not null references batch_employees(id) on delete restrict,material_id uuid not null references learning_materials(id) on delete restrict,opened_at timestamptz,completed_at timestamptz,is_completed boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(batch_employee_id,material_id));
create table if not exists exam_attempts(id uuid primary key default gen_random_uuid(),batch_employee_id uuid not null references batch_employees(id) on delete restrict,attempt_no integer not null check(attempt_no>0),started_at timestamptz not null default now(),deadline_at timestamptz not null,submitted_at timestamptz,duration_seconds integer check(duration_seconds is null or duration_seconds>=0),status attempt_status not null default 'IN_PROGRESS',raw_score numeric(10,2) check(raw_score is null or raw_score>=0),max_score numeric(10,2) check(max_score is null or max_score>0),score_percent numeric(5,2) check(score_percent between 0 and 100),passed boolean,auto_submitted boolean not null default false,review_unlocked boolean not null default false,created_at timestamptz not null default now(),unique(batch_employee_id,attempt_no),check((status='IN_PROGRESS' and submitted_at is null) or (status='SUBMITTED' and submitted_at is not null)));
create unique index if not exists uq_attempt_one_active on exam_attempts(batch_employee_id) where status='IN_PROGRESS'; create index if not exists idx_attempts_employee_started on exam_attempts(batch_employee_id,started_at desc);
create table if not exists attempt_questions(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references exam_attempts(id) on delete restrict,source_question_id uuid references questions(id) on delete set null,display_order integer not null check(display_order>0),question_text_snapshot text not null,explanation_snapshot text,points_snapshot numeric(8,2) not null check(points_snapshot>0),created_at timestamptz not null default now(),unique(attempt_id,display_order));
create table if not exists attempt_question_options(id uuid primary key default gen_random_uuid(),attempt_question_id uuid not null references attempt_questions(id) on delete restrict,source_option_id uuid references question_options(id) on delete set null,display_order integer not null check(display_order>0),option_text_snapshot text not null,is_correct_snapshot boolean not null,created_at timestamptz not null default now(),unique(attempt_question_id,display_order),unique(id,attempt_question_id));
create table if not exists attempt_answers(id uuid primary key default gen_random_uuid(),attempt_question_id uuid not null unique references attempt_questions(id) on delete restrict,selected_option_id uuid not null,is_correct boolean not null,points_awarded numeric(8,2) not null default 0 check(points_awarded>=0),answered_at timestamptz not null default now(),created_at timestamptz not null default now(),constraint fk_answer_option foreign key(selected_option_id,attempt_question_id) references attempt_question_options(id,attempt_question_id) on delete restrict);
do $$ declare t text; begin foreach t in array array['departments','employees','training_courses','learning_materials','question_banks','questions','exams','training_batches','batch_employees','employee_material_progress'] loop execute format('drop trigger if exists trg_%I_updated_at on %I',t,t); execute format('create trigger trg_%I_updated_at before update on %I for each row execute function set_updated_at()',t,t); end loop; end $$;
